WITH filtered AS (SELECT id, full_name, email, dept_id, job_title, hire_date, is_remote, level, LENGTH(level) AS level_length, COALESCE(job_title, 'N/A') AS job_title_filled FROM employees WHERE job_title IS NOT NULL AND hire_date >= '2025-04-01'), enriched AS (SELECT *, ROW_NUMBER() OVER (ORDER BY hire_date, id) AS row_seq, LEAD(level_length, 1, 0) OVER (PARTITION BY level ORDER BY level_length, id) AS next_level_length FROM filtered), deduped AS (SELECT * FROM enriched QUALIFY RANK() OVER (PARTITION BY dept_id, job_title ORDER BY row_seq DESC) = 1), with_windows AS (SELECT *, MIN(next_level_length) OVER w_part AS last3_min_next_level_length, SUM(next_level_length) OVER w_part AS last3_sum_next_level_length, COUNT(next_level_length) OVER w_part AS last3_count_next_level_length, AVG(next_level_length) OVER w_part AS last3_avg_next_level_length, STDDEV_SAMP(row_seq) OVER w_hist AS job_title_stddev_samp_row_seq FROM deduped WINDOW w_part AS (PARTITION BY dept_id ORDER BY row_seq, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY job_title)), scored AS (SELECT *, AVG(last3_count_next_level_length) OVER (ORDER BY last3_min_next_level_length, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS last3_count_next_level_length_avg_6_prior, RANK() OVER (PARTITION BY dept_id ORDER BY next_level_length DESC NULLS LAST) AS next_level_length_rank, SUM(last3_avg_next_level_length) OVER (ORDER BY row_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_last3_avg_next_level_length, NTILE(3) OVER (ORDER BY job_title_stddev_samp_row_seq, id) AS job_title_stddev_samp_row_seq_bucket FROM with_windows), enriched_employees AS (SELECT a.id, a.full_name, a.email, a.dept_id, a.hire_date, a.is_remote, a.level, a.level_length, a.job_title_filled, a.last3_sum_next_level_length, a.last3_count_next_level_length, a.job_title_stddev_samp_row_seq, a.next_level_length_rank, d.location FROM scored a LEFT JOIN departments d ON a.dept_id = d.id), metrics AS (SELECT *, LAG(last3_sum_next_level_length, 1, 0) OVER (PARTITION BY level ORDER BY job_title_stddev_samp_row_seq, id) AS prev_last3_sum_next_level_length, ROW_NUMBER() OVER (PARTITION BY level ORDER BY next_level_length_rank DESC, id) AS row_seq, FIRST_VALUE(level) IGNORE NULLS OVER (PARTITION BY location ORDER BY last3_count_next_level_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_level FROM enriched_employees) SELECT d.dept_name, d.location AS department_location, e.level, COUNT(*) AS cnt, MIN(e.next_level_length_rank) AS min_next_level_length_rank, ROUND(SUM(e.job_title_stddev_samp_row_seq), 2) AS total_job_title_stddev_samp_row_seq FROM metrics e INNER JOIN departments d ON e.dept_id = d.id GROUP BY d.dept_name, d.location, e.level;
